    val SIZE: Int = EN.size

    /** MaterialSpec for a class id, allocated on demand (detection path is cold). */
    fun spec(cls: Int): MaterialSpec {
        val i = cls.coerceIn(0, SIZE - 1)
        return MaterialSpec(MATERIAL[i], RU[i], HEIGHT_M[i], IMPORTANCE[i], 1.5f)
    }
